const app=document.querySelector('#app'),message=document.querySelector('#message');
const esc=x=>String(x??'Unknown').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json=x=>esc(JSON.stringify(x,null,2));let catalogue=null;
async function api(path,body){if(window.__cp8Offline)return window.__cp8Offline.api(path,body);const r=await fetch(path,{...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const value=await r.json();if(!r.ok)throw Error(value.code);return value;}
async function action(fn){try{message.textContent='';await fn();await render();}catch(e){message.textContent=e.message;}}
function button(label,action,secondary=false,disabled=false){return `<button ${disabled?'disabled':''} class="${secondary?'secondary':''}" data-action="${action}">${label}</button>`;}
function finding(title,value,detail,danger=false){return `<section class="card finding ${danger?'danger':''}"><div class="eyebrow">${title}</div><div class="state">${esc(value)}</div><p class="sub">${esc(detail)}</p></section>`;}
function assessment(a){const s=a.evidenceSufficiency;return `<p>Do we understand why usage changed?<br><strong>${esc(s.explanationSufficiency.state)}</strong></p><p>Do we understand resident protection needs?<br><strong>${esc(s.protectionContextSufficiency.state)}</strong></p><p class="sub">${esc(s.explanationSufficiency.primaryExplanation??'No primary explanation established')}</p><table><thead><tr><th>Explanation</th><th>Relative Evidence Support</th></tr></thead><tbody>${a.diagnoses.map(d=>`<tr><td>${esc(d.name)}</td><td>${d.relativeEvidenceSupport.toFixed(1)}%</td></tr>`).join('')}</tbody></table>`;}
async function render(){
 catalogue=await api('/api/cp8/plans');const plans=catalogue.plans,demos=catalogue.demoPlans??[],hash=location.hash.slice(1)||'product';
 if(hash==='qa'){app.innerHTML=`<div class="eyebrow">Technical QA / acceptance cases</div><h1>All outcome scenarios</h1><p class="sub">A–O preserve four separate findings. Open any scenario to inspect actual records, criteria and mapping history.</p>${demos.length?demos.map(d=>`<a class="case" href="#plan/${d.planId}"><b>Case ${esc(d.key)}</b> — ${esc(d.title)}</a>`).join(''):'No synthetic QA catalogue in this saved-plan mode.'}`;return;}
 if(hash==='history'){const list=await api('/api/cp8/reviews');app.innerHTML=`<h1>Saved outcome reviews</h1>${list.map(s=>`<a class="case" href="#plan/${s.plan.planId}"><b>${esc(s.plan.amenityName)} · ${esc(s.plan.pathway)}</b><br>${s.reviews.length} review(s) · ${s.observations.length} immutable observation(s) · ${s.conversions.filter(c=>c.state.startsWith('Disputed')).length} disputed mapping(s)</a>`).join('')||'<p>No outcome reviews recorded yet.</p>'}`;return;}
 const selected=hash.startsWith('plan/')?hash.slice(5):demos[0]?.planId??plans[0]?.planId,plan=plans.find(p=>p.planId===selected);
 if(!plan){app.innerHTML='<h1>Outcome Review</h1><div class="card">No saved CP7 approval is available. Approve a plan in CP7 first. Eligibility alone is not approval.</div>';return;}
 const s=await api('/api/cp8/reviews',{planId:plan.planId,operatorId:'Simulated outcome reviewer'}),demo=demos.find(d=>d.planId===plan.planId),r=s.reviews.at(-1),c=s.conversions.at(-1),updated=s.reassessments.at(-1),canonical=demos.filter(d=>['A','E','H','M','N'].includes(d.key));
 app.innerHTML=`<div class="layout"><aside class="sidebar">${(canonical.length?canonical:plans.map(p=>({planId:p.planId,title:p.pathway}))).map(d=>`<a class="case ${d.planId===plan.planId?'active':''}" href="#plan/${d.planId}">${esc(d.title)}</a>`).join('')}</aside><article><div class="eyebrow">${esc(plan.amenityName)} / Outcome Review</div><h1>Did the plan fulfil its purpose?</h1><p class="sub">${esc(plan.pathway)} · ${esc(plan.scope.purpose)}</p><div class="journey"><span>Plan approved</span>→<span>External activity evidenced</span>→<span>Purpose + protection reviewed</span>→<span>Evidence feedback where justified</span></div>
 ${demo?'<p class="sub" style="font-size:12px">Simulated external records · review time 15 September 2026 · no real intervention performed.</p>':''}${s.currentValidity!=='Current'?`<div class="notice">${esc(s.currentValidity)}. Historical findings are retained; no new feedback is authorised.</div>`:''}${s.newerInputsAvailable?'<div class="notice">Newer evidence is available. Re-evaluate before confirming an earlier mapping.</div>':''}
 ${r?`<div class="findings">${finding('Was the plan carried out?',r.executionFinding.state,r.executionFinding.reason)}${finding('Did it meet its purpose?',r.goalFinding.state,`Intervention benefit: ${r.goalFinding.interventionBenefit}. Evidence purpose: ${r.goalFinding.evidencePurpose}.`)}${finding('Was protected access maintained?',r.protectionFinding.state,r.protectionFinding.state==='Protection breach'?'This breach cannot be offset by aggregate benefit. No rollback or execution command was issued.':'Protected access is evaluated separately from benefit.',r.protectionFinding.state==='Protection breach')}${finding('What does this tell us about the explanation?',updated?.diagnosisFinding?.state??r.diagnosisFinding.state,updated?'The unchanged CP3 engine evaluated an admissible child evidence snapshot. No causal proof.':r.diagnosisFinding.inference)}</div>`:`<section class="card"><span class="tag">Approved plan · execution not established</span><h2>Approval is the beginning of review, not proof of delivery.</h2><p>Bring in documentary evidence of external activity and the observations required by the approved contract.</p>${demo?button('Load simulated external records & review','import'):''}</section>`}
 ${r?`<section class="card"><h2>Observed against the approved purpose</h2><table><thead><tr><th>Measure</th><th>Observed</th><th>Finding</th></tr></thead><tbody>${r.criteria.map(x=>`<tr><td>${esc(x.literal)}</td><td>${x.observed.map(o=>esc(o.value)).join(' / ')||'Unknown'}</td><td>${esc(x.state)}</td></tr>`).join('')}</tbody></table>${r.ambiguities.length?`<div class="notice">Approved criteria are ambiguous or unspecified. No retrospective success standard has been invented.</div>`:''}</section>`:''}
 ${c?`<section class="card"><h2>Evidence feedback</h2><span class="tag">${esc(c.state)}</span><p>${esc(c.inference)}</p><p class="sub">${esc(c.cannotEstablish)}</p>${c.state==='Admissible — awaiting confirmation'?`<div class="notice">Review mapping correctness, not whether the finding is favourable. An unconfirmed or disputed mapping remains visible.</div><label><input type="checkbox" id="ack"> I reviewed the original reference period, source and exact input mapping.</label>${button('Confirm mapping & reassess','confirm',false,true)}<label>Mapping concern / dispute reason<input type="text" id="reason" placeholder="Explain the source or mapping issue"></label>${button('Record mapping dispute','dispute',true)}`:''}${c.state==='Disputed mapping / review required'?'<div class="notice">Dispute remains in history. A versioned source/mapping correction is required; the evidence cannot be hidden or forced into CP3.</div>':''}${c.reasons?.length?`<p>${c.reasons.map(esc).join('<br>')}</p>`:''}</section>`:''}
 ${updated?`<section class="card"><h2>Evidence changed. The engine reassessed.</h2><p>${esc(updated.diagnosisFinding.target)}: ${esc(updated.diagnosisFinding.state)}. Relative Evidence Support is not causal probability.</p><div class="compare"><div><h3>Before feedback</h3>${assessment(updated.originalAssessment)}</div><div><h3>After feedback</h3>${assessment(updated.assessment)}</div></div></section>`:''}
 <details><summary>Approved scope & exact Outcome Contract</summary><p>${esc(plan.scope.scopeBounds.extent)}</p><p><b>Protected access:</b> ${esc(plan.scope.scopeBounds.protectedAccess)}</p><p><b>Review window:</b> ${esc(plan.scope.outcomeContract.reviewWindow.start)} → ${esc(plan.scope.outcomeContract.reviewWindow.end)}</p><pre>${esc(plan.scope.outcomeContract.criteria)}</pre><p>Interpretation frozen before outcome admission. Unrecognised prose remains ambiguous.</p></details>
 <details><summary>Evidence, provenance & technical details</summary><pre>${json({binding:s.binding,executions:s.executions,observations:s.observations,reviews:s.reviews,conversions:s.conversions})}</pre></details>
 <details><summary>Record externally produced evidence</summary><p class="sub">Documentary input only. These forms do not execute a plan. Sources and qualification are trusted demonstration inputs, not verified external integrations.</p><label>External execution evidence JSON<textarea id="execution-json" placeholder="Paste a provenance-linked external execution record"></textarea></label>${button('Record execution evidence','execution',true)}<label>Outcome observation JSON<textarea id="observation-json" placeholder="Paste a versioned observed-evidence record"></textarea></label>${button('Record observation','observation',true)}<p>${button('Evaluate current evidence','evaluate',true)}</p></details>
 <details><summary>Immutable review history</summary><pre id="history-content">${json(await api(`/api/cp8/reviews/${s.id}/history`))}</pre></details></article></div>`;
 const request=extra=>({expectedRevision:s.revision,idempotencyKey:crypto.randomUUID(),...extra});
 document.querySelector('#ack')?.addEventListener('change',ev=>{document.querySelector('[data-action="confirm"]').disabled=!ev.target.checked;});
 app.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>action(async()=>{
  const type=el.dataset.action;
  if(type==='import')await api(`/api/cp8/reviews/${s.id}/demo-import`,{});
  if(type==='confirm'||type==='dispute')await api(`/api/cp8/reviews/${s.id}/confirm`,request({conversionId:c.id,operatorId:'Simulated outcome reviewer',choice:type==='confirm'?'confirm':'dispute',...(type==='dispute'?{reason:document.querySelector('#reason').value}:{})}));
  if(type==='execution'||type==='observation')await api(`/api/cp8/reviews/${s.id}/${type==='execution'?'execution-evidence':'observations'}`,request({record:JSON.parse(document.querySelector(type==='execution'?'#execution-json':'#observation-json').value)}));
  if(type==='evaluate')await api(`/api/cp8/reviews/${s.id}/evaluate`,request({asOf:demo?'2026-09-15T12:00:00.000Z':new Date().toISOString()}));
 })));
}
window.addEventListener('hashchange',()=>action(async()=>{}));await action(async()=>{});
